Top 10 Trusts with highest breach rate                                                                                                                                 SELECT                                                                                                                                                             Provider_Name,                                                                                                                                                        Total_Attendances,                                                                                                                                                    Breaches_Over_4hrs,                                                                                                                                                    ROUND(Breaches_over_4hrs*1.0/Total_Attendances*100),2)AS Breach_Rate_Pct                                                                                              FROM ae_data                                                                                                                                                          ORDER BY Breach_Rate_Pct DESC                                                                                                                                         LIMIT 10;
Average breach rates across all Trusts                                                                                                                                 SELECT                                                                                                                                                                ROUND(AVG(Breaches_over_4hrs*1.0/Total_Attendances*100),2)AS Avg_Breach_Rate_Pct,                                                                                     COUNT(*) AS Total_Trusts                                                                                                                                              FROM ae_data;
Trusts meeting vs missing the 95% target(less than 5%breach)                                                                                                           SELECT                                                                                                                                                                CASE WHEN(Breaches_over_4hrs*1.0/Total_Attendances)<=0.05 THEN'MET TARGET' ELSE 'MISSED TARGET' END AS Target_Status,                                                 COUNT(*)AS Num_Trusts                                                                                                                                                 FROM ae_data                                                                                                                                                          GROUP BY Target_Status
